		fmt.Scan(&ar[i].a, &ar[i].b)
	}

	sort.Slice(ar, func(i, j int) bool {
		return ar[i].a < ar[j].a
	})

	if ar[0].a != ar[1].a || ar[0].a != ar[2].a {
		fmt.Println("ugly")
