		fmt.Println("ugly")
	} else if ar[0].a == ar[7].a {
		fmt.Println("ugly")
	} else if ar[0].a == ar[3].a {
		fmt.Println("ugly")
	} else {
		x, y, z := ar[0].b, ar[1].b, ar[2].b
		if x == y || x == z {
			fmt.Println("ugly")
		} else {
			minVal := 10000000
			maxVal := -1
			outerBreak := false
			for xIdx := 5; xIdx < 8; xIdx++ {
				if ar[xIdx].b < minVal {
					minVal = ar[xIdx].b
				}
				if ar[xIdx].b > maxVal {
